// frontend/src/components/Search.js

import React, { useState, useContext } from "react";
import axios from "../utils/axiosInstance";
import GeneralContext from "./GeneralContext";

const Search = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const { refreshWatchlist } = useContext(GeneralContext);

  const handleSearch = async (e) => {
    const val = e.target.value;
    setQuery(val);
    if (val.length < 2) {
      setResults([]);
      return;
    }

    try {
      const res = await axios.get(`/api/search?q=${val}`);
      setResults(res.data);
    } catch (err) {
      console.error("Search error:", err);
    }
  };

  const addToWatchlist = async (symbol) => {
    try {
      await axios.post("/api/watchlist", { symbol });
      refreshWatchlist();
      setQuery("");
      setResults([]);
    } catch (err) {
      console.error("Add failed:", err);
    }
  };

  return (
    <div className="search-container">
      <input
        type="text"
        value={query}
        onChange={handleSearch}
        placeholder="Search stocks e.g. INFY, SBIN"
        className="search"
      />
      {results.length > 0 && (
        <ul className="search-results">
          {results.map((stock, idx) => (
            <li key={idx} onClick={() => addToWatchlist(stock.symbol)}>
              {stock.name} ({stock.symbol}) - ₹{stock.price} - {stock.exchange}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Search;
